import org.testcontainers.utility.DockerImageName;
@Testcontainers class RedactionPreviewMigrationIT {
 @Container static final PostgreSQLContainer DB=new PostgreSQLContainer(DockerImageName.parse("postgres@sha256:74935e72241653ca55e0414067e6d8763aceb8a810eb51b452253ec3dcfc4336").asCompatibleSubstituteFor("postgres"));
 @Test void populated73RetainsOriginalCaseAuditAndLivePermitThenRestrictedProjectionWorks()throws Exception{
  Flyway.configure().dataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword()).target("20261022130000").load().migrate();var ds=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());var owner=new JdbcTemplate(ds);var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));var clock=Clock.fixed(Instant.parse("2026-10-22T12:00:00Z"),ZoneOffset.UTC);var ids=new UuidGenerator(clock);UUID subject=ids.next(),operator=ids.next(),org=ids.next(),session=ids.next(),source=ids.next();Timestamp at=Timestamp.from(clock.instant());
  tx.executeWithoutResult(s->{for(UUID id:List.of(subject,operator))owner.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state) VALUES(?,?,?,true,'Synthetic','ACTIVE')",id,id.equals(operator)?"PLATFORM_ADMIN":"BUSINESS",id+"@example.com");owner.update("INSERT INTO platform_account(id) VALUES(?)",operator);owner.update("INSERT INTO organization(id,type,country,currency,display_name,legal_name,registration_identifier,address_line1,address_city,address_postal_code,address_country,default_language,state,owner_account_id) VALUES(?,'BUYER','BA','BAM','Synthetic','Synthetic','SYN-REDACTION-MIGRATION','Synthetic','Synthetic','11000','BA','en','ACTIVE',?)",org,subject);owner.update("INSERT INTO business_account(id,organization_id,role) VALUES(?,?,'OWNER')",subject,org);owner.execute("SET LOCAL narudzbine.operator_change_reference='SYN-MIGRATION'");owner.update("INSERT INTO privacy_operator(account_id,created_at) VALUES(?,?)",operator,at);owner.update("INSERT INTO application_session(id,account_id,transport,token_hash,device_label,created_at,last_qualified_activity_at,absolute_expires_at,auth_at,auth_method_type,credential_generation,security_epoch) VALUES(?,?,'NATIVE',?,'Synthetic',?,?,?,?,'PASSWORD',0,0)",session,operator,new byte[32],at,at,Timestamp.from(clock.instant().plusSeconds(43200)),at);owner.update("INSERT INTO privacy_case(id,requester_id,organization_id,country,kind,private_reason,created_at) VALUES(?,?,?,'BA','REDACTION','SYNTHETIC-PRIVATE-REASON',?)",source,subject,org,at);});
  var review=new JdbcPrivateCaseReview(owner,clock,ids);var access=tx.execute(s->review.authorize(source,new PrivateCaseReview.Target(org,"BA"),new PrivateCaseReview.Actor(operator,session,"NATIVE"),new PrivateCaseReview.Context("Synthetic migration preview","SYN-MIGRATION")));var cases=owner.queryForList("SELECT to_jsonb(c)::text AS snapshot FROM privacy_case c");var evidence=owner.queryForList("SELECT to_jsonb(a)::text AS snapshot FROM audit_event a ORDER BY id");var permits=owner.queryForList("SELECT to_jsonb(p)::text AS snapshot FROM privacy_review_access p");MigrationCommand.migrate(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());MigrationCommand.migrate(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());assertThat(owner.queryForList("SELECT to_jsonb(c)::text AS snapshot FROM privacy_case c")).isEqualTo(cases);assertThat(owner.queryForList("SELECT to_jsonb(a)::text AS snapshot FROM audit_event a ORDER BY id")).isEqualTo(evidence);assertThat(owner.queryForList("SELECT to_jsonb(p)::text AS snapshot FROM privacy_review_access p")).isEqualTo(permits);new DatabaseReadiness(ds).verifySchema();
  owner.execute("CREATE ROLE migration_preview NOLOGIN");owner.execute("GRANT USAGE ON SCHEMA public TO migration_preview");owner.execute("GRANT SELECT ON privacy_operator TO migration_preview");owner.execute("GRANT UPDATE(account_id) ON privacy_operator TO migration_preview");owner.execute("GRANT INSERT ON audit_event,privacy_review_read TO migration_preview");owner.execute("GRANT EXECUTE ON FUNCTION inspect_redaction_preview(uuid,bytea,uuid,uuid,text,timestamptz) TO migration_preview");var restricted=new DelegatingDataSource(ds){@Override public Connection getConnection()throws SQLException{var c=super.getConnection();try(var statement=c.createStatement()){statement.execute("SET ROLE migration_preview");}return c;}};var jdbc=new JdbcTemplate(restricted);var preview=new JdbcRedactionPreviews(jdbc,clock,ids,new JdbcPrivateCaseReview(jdbc,clock,ids));var result=new TransactionTemplate(new DataSourceTransactionManager(restricted)).execute(s->preview.inspect(access));assertThat(result.subjectAccountId()).isEqualTo(subject);assertThat(result.blockers()).contains("OWNER_TRANSFER_OR_REVIEW_REQUIRED");assertThat(owner.queryForObject("SELECT count(*) FROM audit_event WHERE action='PRIVACY_REDACTION_PREVIEWED'",Integer.class)).isEqualTo(1);assertThatThrownBy(()->jdbc.queryForList("SELECT * FROM privacy_case")).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThatThrownBy(()->jdbc.queryForList("SELECT * FROM audit_event")).isInstanceOf(org.springframework.dao.DataAccessException.class);
 }
}
